    private void gentareJson()
    {
        for (int i = 0; i < 500; i++)
        {
            mTrackAttribute.Add(new
            {
                timestamp = start.AddMinutes(i).ToString("dd/MM/yyyy HH:mm:ss"),

                ITC_FEED_END_mA = 438.34 + Random.Shared.NextDouble() * 5,
                OTC_RELAY_END_mA = 348.97 + Random.Shared.NextDouble() * 5,
                VTC_RELAY_END_V = 3.64 + Random.Shared.NextDouble(),
                VTC_CH_FEED_END_V = 1.15 + Random.Shared.NextDouble(),
                ITC_TFC_OP_mA = 789.5 + Random.Shared.NextDouble() * 10,
                VTC_24_DCTPR_IP_V = 23.81 + Random.Shared.NextDouble(),
                VTC_FEED_END_V = 4.15 + Random.Shared.NextDouble(),
                VTC_TFC_IP_V = 113.12 + Random.Shared.NextDouble() * 2,
                VTC_TFC_OP_V = 1.59 + Random.Shared.NextDouble(),
                VTC_24_DC_LOC_V = 26.36 + Random.Shared.NextDouble(),
                Leakage = 89.37 + Random.Shared.NextDouble() * 3
            });
        }

        string json = JsonSerializer.Serialize(mTrackAttribute, new JsonSerializerOptions
        {
            WriteIndented = true
        });

        //File.WriteAllText("single-line-series-500.json", json);
    }
