    public class SensorSnapshot
    {
        public string timestamp { get; set; }

        public double ITC_FEED_END_mA { get; set; }
        public double OTC_RELAY_END_mA { get; set; }
        public double VTC_RELAY_END_V { get; set; }
        public double VTC_CH_FEED_END_V { get; set; }
        public double ITC_TFC_OP_mA { get; set; }
        public double VTC_24_DCTPR_IP_V { get; set; }
        public double VTC_FEED_END_V { get; set; }
        public double VTC_TFC_IP_V { get; set; }
        public double VTC_TFC_OP_V { get; set; }
        public double VTC_24_DC_LOC_V { get; set; }
        public double Leakage { get; set; }

        // Parsed DateTime (for chart)
        public DateTime Timestamp =>
            DateTime.ParseExact(
                timestamp,
                "dd/MM/yyyy HH:mm:ss",
                CultureInfo.InvariantCulture);
    }

    public class SensorPoint
    {
        public DateTime Timestamp { get; set; }
        public double Value { get; set; }
        public string SensorName { get; set; }
    }

    private void LoadData()
    {
        chart.Series.Clear();
        var sensorData = JsonSerializer.Deserialize<List<SensorSnapshot>>(sensorJson);

        // Sample data - each sensor needs multiple points to form a line
        var rawData = new List<string[]>
    {
        // ITC FEED END(mA) - Multiple points for this sensor
        new string[] { "400", "05:00", "ITC FEED END(mA)" },
        new string[] { "420", "05:15", "ITC FEED END(mA)" },
        new string[] { "438.34", "05:45", "ITC FEED END(mA)" },
        new string[] { "450", "06:00", "ITC FEED END(mA)" },
        //ifma
        //irms
        //
        
        // ITC RELAY END(mA) - Multiple points
        new string[] { "320", "05:00", "ITC RELAY END(mA)" },
        new string[] { "340", "05:30", "ITC RELAY END(mA)" },
        new string[] { "348.97", "05:50", "ITC RELAY END(mA)" },
        
        // ITC RELAY END(V) - Multiple points
        new string[] { "2.5", "05:00", "ITC RELAY END(V)" },
        new string[] { "3.0", "05:30", "ITC RELAY END(V)" },
        new string[] { "3.64", "05:55", "ITC RELAY END(V)" },
        
        // Add more points for other sensors...
    };

        var groupedData = rawData.GroupBy(x => x[2]);
        int colorIndex = 0;
        Color[] seriesColors =
        {
        Colors.Teal,
        Colors.Orange,
        Colors.DodgerBlue,
        Colors.Green,
        Colors.Purple,
        Colors.Red,
        Colors.Black
    };

        foreach (var group in groupedData)
        {
            // Only create series if we have enough points
            if (group.Count() >= 2)
            {
                var lineSeries = new SplineSeries
                {
                    Label = group.Key,
                    XBindingPath = "Timestamp",
                    YBindingPath = "Value",
                    StrokeWidth = 2,
                    ShowMarkers = true,
                    //StrokeDashArray = new SolidColorBrush(seriesColors[colorIndex % seriesColors.Length]),
                    MarkerSettings = new ChartMarkerSettings
                    {
                        Fill = Colors.White,
                        Stroke = seriesColors[colorIndex % seriesColors.Length],
                        StrokeWidth = 2,
                        //Shape = ChartMarkerShape.Circle,
                        Height = 8,
                        Width = 8
                    },
                    ItemsSource = group.Select(item => new SensorData
                    {
                        Value = double.Parse(item[0]),
                        Timestamp = DateTime.ParseExact(item[1], "HH:mm", CultureInfo.InvariantCulture),
                        SensorName = item[2]
                    }).OrderBy(x => x.Timestamp).ToList()
                };

                chart.Series.Add(lineSeries);
                colorIndex++;
            }
        }

        chart.InvalidateMeasure();
    }
    private List<SensorPoint> FlattenSensorData(List<SensorSnapshot> data)
    {
        var list = new List<SensorPoint>();

        foreach (var row in data)
        {
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.ITC_FEED_END_mA, SensorName = "ITC FEED END (mA)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.OTC_RELAY_END_mA, SensorName = "OTC RELAY END (mA)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.VTC_RELAY_END_V, SensorName = "VTC RELAY END (V)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.VTC_CH_FEED_END_V, SensorName = "VTC CH FEED END (V)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.ITC_TFC_OP_mA, SensorName = "ITC TFC O/P (mA)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.VTC_24_DCTPR_IP_V, SensorName = "VTC 24 DCTPR I/P (V)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.VTC_FEED_END_V, SensorName = "VTC FEED END (V)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.VTC_TFC_IP_V, SensorName = "VTC TFC I/P (V)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.VTC_TFC_OP_V, SensorName = "VTC TFC O/P (V)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.VTC_24_DC_LOC_V, SensorName = "VTC 24 DC LOC (V)" });
            list.Add(new SensorPoint { Timestamp = row.Timestamp, Value = row.Leakage, SensorName = "Leakage" });
        }

        return list;
    }
    private void LoadChartDat()
    {
        chart.Series.Clear();

        var snapshots = JsonSerializer.Deserialize<List<SensorSnapshot>>(sensorJson);

        var flatData = FlattenSensorData(snapshots);

        var groupedData = flatData.GroupBy(x => x.SensorName);

        Color[] seriesColors =
        {
            Colors.Teal,
            Colors.Orange,
            Colors.DodgerBlue,
            Colors.Green,
            Colors.Purple,
            Colors.Red,
            Colors.Brown,
            Colors.DarkCyan,
            Colors.DarkMagenta,
            Colors.DarkOliveGreen,
            Colors.Black
        };

        int colorIndex = 0;

        foreach (var group in groupedData)
        {
            if (group.Count() < 2)
                continue;

            var series = new SplineSeries
            {
                Label = group.Key,
                XBindingPath = nameof(SensorPoint.Timestamp),
                YBindingPath = nameof(SensorPoint.Value),
                StrokeWidth = 2,
                ShowMarkers = true,
                ItemsSource = group.OrderBy(x => x.Timestamp).ToList(),

                MarkerSettings = new ChartMarkerSettings
                {
                    Fill = Colors.White,
                    Stroke = seriesColors[colorIndex % seriesColors.Length],
                    StrokeWidth = 2,
                    Height = 8,
                    Width = 8
                }
            };

            chart.Series.Add(series);
            colorIndex++;
        }
    }



