    private void InitializeRailwayZones()
    {
        // Static list of all Indian Railway Zones (sorted by ZoneCode)
        var zones = new List<RailwayZone>
        {
            new RailwayZone { Id = 1, ZoneCode = "CR", ZoneName = "Central Railway", Headquarters = "Mumbai" },
            new RailwayZone { Id = 2, ZoneCode = "ER", ZoneName = "Eastern Railway", Headquarters = "Kolkata" },
            new RailwayZone { Id = 3, ZoneCode = "ECR", ZoneName = "East Central Railway", Headquarters = "Hajipur" },
            new RailwayZone { Id = 4, ZoneCode = "ECoR", ZoneName = "East Coast Railway", Headquarters = "Bhubaneswar" },
            new RailwayZone { Id = 5, ZoneCode = "NR", ZoneName = "Northern Railway", Headquarters = "New Delhi" },
            new RailwayZone { Id = 6, ZoneCode = "NCR", ZoneName = "North Central Railway", Headquarters = "Prayagraj" },
            new RailwayZone { Id = 7, ZoneCode = "NER", ZoneName = "North Eastern Railway", Headquarters = "Gorakhpur" },
            new RailwayZone { Id = 8, ZoneCode = "NFR", ZoneName = "Northeast Frontier Railway", Headquarters = "Guwahati" },
            new RailwayZone { Id = 9, ZoneCode = "NWR", ZoneName = "North Western Railway", Headquarters = "Jaipur" },
            new RailwayZone { Id = 10, ZoneCode = "SR", ZoneName = "Southern Railway", Headquarters = "Chennai" },
            new RailwayZone { Id = 11, ZoneCode = "SCR", ZoneName = "South Central Railway", Headquarters = "Secunderabad" },
            new RailwayZone { Id = 12, ZoneCode = "SER", ZoneName = "South Eastern Railway", Headquarters = "Kolkata" },
            new RailwayZone { Id = 13, ZoneCode = "SECR", ZoneName = "South East Central Railway", Headquarters = "Bilaspur" },
            new RailwayZone { Id = 14, ZoneCode = "SCoR", ZoneName = "South Coast Railway", Headquarters = "Visakhapatnam" },
            new RailwayZone { Id = 15, ZoneCode = "SWR", ZoneName = "South Western Railway", Headquarters = "Hubli" },
            new RailwayZone { Id = 16, ZoneCode = "WR", ZoneName = "Western Railway", Headquarters = "Mumbai" },
            new RailwayZone { Id = 17, ZoneCode = "WCR", ZoneName = "West Central Railway", Headquarters = "Jabalpur" },
            new RailwayZone { Id = 18, ZoneCode = "ConR", ZoneName = "Konkan Railway", Headquarters = "Navi Mumbai" },
            new RailwayZone { Id = 19, ZoneCode = "Metro", ZoneName = "Metro Railway", Headquarters = "Kolkata" }
        };

        // Sort by ZoneCode
        RailwayZones = new ObservableCollection<RailwayZone>(zones.OrderBy(z => z.ZoneCode));
        zoneCollectionView.ItemsSource = RailwayZones;

        // Initialize all divisions
        InitializeAllDivisions();
    }

    private void ChkSelectAll_CheckedChanged(object sender, CheckedChangedEventArgs e)
    {
        //if (_isUpdatingSelectAll) return;

        foreach (var zone in RailwayZones)
        {
            zone.IsSelected = e.Value;
        }

        // Update divisions based on selected zones
        UpdateDivisionsBasedOnSelectedZones();
    }

    private void ZoneCheckBox_CheckedChanged(object sender, CheckedChangedEventArgs e)
    {
        UpdateSelectAllState();
        // Update divisions based on selected zones
        UpdateDivisionsBasedOnSelectedZones();
    }

    private void UpdateSelectAllState()
    {
        if (RailwayZones == null || RailwayZones.Count == 0) return;

        _isUpdatingSelectAll = true;
        chkSelectAll.IsChecked = RailwayZones.All(z => z.IsSelected);
        _isUpdatingSelectAll = false;
    }

    private async void BtnSearch_Clicked(object sender, EventArgs e)
    {
        var selectedZones = RailwayZones.Where(z => z.IsSelected).ToList();

        if (selectedZones.Count == 0)
        {
            await DisplayAlert("Selection", "Please select at least one zone", "OK");
            return;
        }

        // Display selected zones (you can replace this with your actual search logic)
        var selectedZoneCodes = string.Join(", ", selectedZones.Select(z => z.ZoneCode));
        await DisplayAlert("Selected Zones", $"You selected: {selectedZoneCodes}", "OK");
    }

    private void BtnClear_Clicked(object sender, EventArgs e)
    {
        _isUpdatingSelectAll = true;
        chkSelectAll.IsChecked = false;
        _isUpdatingSelectAll = false;

        foreach (var zone in RailwayZones)
        {
            zone.IsSelected = false;
        }

        // Clear divisions too
        UpdateDivisionsBasedOnSelectedZones();
    }

