    private void UpdateDivisionsBasedOnSelectedZones()
    {
        var selectedZoneIds = RailwayZones.Where(z => z.IsSelected).Select(z => z.Id).ToList();

        FilteredDivisions.Clear();
        chkSelectAllDivisions.IsChecked = false;

        if (selectedZoneIds.Count > 0)
        {
            var divisions = AllDivisions
                .Where(d => selectedZoneIds.Contains(d.ZoneId))
                .OrderBy(d => d.DivisionCode)
                .ToList();

            foreach (var division in divisions)
            {
                division.IsSelected = false;  // Reset selection
                FilteredDivisions.Add(division);
            }
        }
    }

    private void ChkSelectAllDivisions_CheckedChanged(object sender, CheckedChangedEventArgs e)
    {
        if (_isUpdatingSelectAllDivisions) return;

        foreach (var division in FilteredDivisions)
        {
            division.IsSelected = e.Value;
        }
    }

    private void DivisionCheckBox_CheckedChanged(object sender, CheckedChangedEventArgs e)
    {
        UpdateSelectAllDivisionsState();
    }

    private void UpdateSelectAllDivisionsState()
    {
        if (FilteredDivisions == null || FilteredDivisions.Count == 0) return;

        _isUpdatingSelectAllDivisions = true;
        chkSelectAllDivisions.IsChecked = FilteredDivisions.All(d => d.IsSelected);
        _isUpdatingSelectAllDivisions = false;
    }

    private async void BtnSearchDivisions_Clicked(object sender, EventArgs e)
    {
        var selectedDivisions = FilteredDivisions.Where(d => d.IsSelected).ToList();

        if (selectedDivisions.Count == 0)
        {
            await DisplayAlert("Selection", "Please select at least one division", "OK");
            return;
        }

        // Display selected divisions
        var selectedDivisionCodes = string.Join(", ", selectedDivisions.Select(d => d.DivisionCode));
        await DisplayAlert("Selected Divisions", $"You selected: {selectedDivisionCodes}", "OK");
    }

    private void BtnClearDivisions_Clicked(object sender, EventArgs e)
    {
        _isUpdatingSelectAllDivisions = true;
        chkSelectAllDivisions.IsChecked = false;
        _isUpdatingSelectAllDivisions = false;

        foreach (var division in FilteredDivisions)
        {
            division.IsSelected = false;
        }
    }

